// Failure modes: a task becomes shell syntax; a follow-up creates another browser session; an invalid URL or session
// reaches the browser; a failed bridge is reported as success or retried; the recipe works only inside this repository.
import assert from "node:assert/strict";
import { spawnSync } from "node:child_process";
import { copyFileSync, existsSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { after, test } from "node:test";

const root = mkdtempSync(join(tmpdir(), "autoloop-browser-template-"));
after(() => rmSync(root, { recursive: true, force: true }));
const session = "12345678-1234-1234-1234-123456789abc";

function fixture() {
  const dir = mkdtempSync(join(root, "case-"));
  copyFileSync(join(import.meta.dirname, "../examples/recipes/browser-handoff/handoff.ts"), join(dir, "handoff.ts"));
  const command = join(dir, "browser entry");
  writeFileSync(
    command,
    `#!${process.execPath}
import fs from 'node:fs';
fs.appendFileSync('called.jsonl', JSON.stringify(process.argv.slice(2))+'\\n');
console.log('页面证据：示例页面标题');
console.log('[Codex 会话 ID：${session}]');
process.exit(Number(process.env.BRIDGE_EXIT || 0));
`,
    { mode: 0o755 },
  );
  const task = {
    command: [command],
    url: "https://example.com/页面",
    checks: ["核实标题", "保留字面量 $(touch SHOULD_NOT_EXIST) 和 `echo x`"],
    allowedActions: ["只读页面", "仅关闭本次新建的标签"],
  };
  writeFileSync(join(dir, "browser.json"), JSON.stringify(task));
  const run = (args: string[] = [], code = 0) =>
    spawnSync(process.execPath, ["handoff.ts", "browser.json", ...args], {
      cwd: dir,
      encoding: "utf8",
      env: { ...process.env, BRIDGE_EXIT: String(code) },
    });
  return { dir, task, run };
}

test("the standalone launcher passes one literal task, preserves evidence and resumes the supplied session", () => {
  const { dir, run } = fixture();
  const first = run();
  assert.equal(first.status, 0, first.stderr);
  assert.match(first.stdout, /页面证据/);
  assert.ok(first.stdout.includes(session));
  assert.equal(existsSync(join(dir, "SHOULD_NOT_EXIST")), false);
  const again = run(["--resume", session]);
  assert.equal(again.status, 0, again.stderr);
  const calls: string[][] = readFileSync(join(dir, "called.jsonl"), "utf8")
    .trim()
    .split("\n")
    .map((line) => JSON.parse(line));
  assert.equal(calls[0].length, 1);
  assert.ok(calls[0][0].includes("$(touch SHOULD_NOT_EXIST)"));
  assert.ok(calls[0][0].includes(new URL("https://example.com/页面").href));
  assert.deepEqual(calls[1].slice(0, 2), ["--resume", session]);
  assert.equal(calls[1].length, 3);
});

test("invalid scope or resume arguments do not launch a browser", () => {
  const { dir, task, run } = fixture();
  assert.notEqual(run(["--resume", "bad; command"]).status, 0);
  assert.notEqual(run(["--resume"]).status, 0);
  assert.notEqual(run(["--other"]).status, 0);
  writeFileSync(join(dir, "browser.json"), JSON.stringify({ ...task, url: "javascript:alert(1)" }));
  assert.notEqual(run().status, 0);
  assert.equal(existsSync(join(dir, "called.jsonl")), false);
});

test("a failed bridge keeps its evidence and exit code, with no retry", () => {
  const { dir, run } = fixture();
  const failed = run([], 23);
  assert.equal(failed.status, 23);
  assert.match(failed.stdout, /页面证据/);
  assert.equal(readFileSync(join(dir, "called.jsonl"), "utf8").trim().split("\n").length, 1);
});

// Failure modes: stdout contains non-protocol text; unknown tools execute arbitrary endpoints; malformed arguments reach
// the hub; an HTTP failure becomes a successful tool result; notifications get responses; source keys act as owner keys;
// a client is told a version number left behind by a release; a slow tool call holds up a ping or another call, or is
// dropped when the input ends while it's in hand; a U+2028 or U+2029 in a request, which JSON leaves as it is, cuts the
// line, so the request never gets an answer.
import assert from "node:assert/strict";
import { spawn } from "node:child_process";
import { once } from "node:events";
import { writeFileSync } from "node:fs";
import { join } from "node:path";
import { test } from "node:test";
import { createServer, type RequestListener } from "node:http";
import { versionName } from "../host/version.ts";
import { setup } from "./helpers.ts";
const home = setup("mcp");

/** The MCP server for real, against a stand-in hub, past its handshake. */
async function connect(hub: RequestListener) {
  const server = createServer(hub);
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  writeFileSync(
    join(home, "config.json"),
    JSON.stringify({
      url: `http://127.0.0.1:${(server.address() as any).port}`,
      owner: "owner-key",
      source: { name: "app", key: "source-key" },
    }),
  );
  const child = spawn(process.execPath, ["bin/agent-autoloop.ts", "mcp"], {
    cwd: join(import.meta.dirname, ".."),
    env: process.env,
    stdio: ["pipe", "pipe", "inherit"],
  });
  // Watched from the start: it can be gone by the time a test looks.
  const closed = once(child, "close");
  let output = "";
  child.stdout.on("data", (b) => (output += b));
  const answers = () =>
    output
      .split("\n")
      .filter(Boolean)
      .map((line) => JSON.parse(line));
  const send = (message: object) => child.stdin.write(JSON.stringify({ jsonrpc: "2.0", ...message }) + "\n");
  const answered = async (id: number) => {
    const end = Date.now() + 5_000;
    for (;;) {
      const answer = answers().find((answer) => answer.id === id);
      if (answer) return answer;
      if (Date.now() > end) assert.fail(`nothing came back for ${id}`);
      await new Promise((resolve) => setTimeout(resolve, 10));
    }
  };
  const close = async () => {
    child.kill();
    server.closeAllConnections();
    await new Promise((resolve) => server.close(resolve));
  };
  send({
    id: 1,
    method: "initialize",
    params: { protocolVersion: "2025-11-25", capabilities: {}, clientInfo: { name: "test", version: "1" } },
  });
  send({ method: "notifications/initialized" });
  await answered(1);
  return { child, closed, send, answers, answered, close };
}

test("MCP stdio initializes and exposes only the typed hub operations", async () => {
  const calls: any[] = [];
  const server = createServer((req, res) => {
    calls.push([req.url, req.headers.authorization]);
    res.statusCode = req.url?.includes("999") ? 404 : 200;
    res.end(JSON.stringify({ ok: true }));
  });
  server.listen(0, "127.0.0.1");
  await once(server, "listening");
  writeFileSync(
    join(home, "config.json"),
    JSON.stringify({
      url: `http://127.0.0.1:${(server.address() as any).port}`,
      owner: "owner-key",
      source: { name: "app", key: "source-key" },
    }),
  );
  const child = spawn(process.execPath, ["bin/agent-autoloop.ts", "mcp"], {
    cwd: join(import.meta.dirname, ".."),
    env: process.env,
    stdio: ["pipe", "pipe", "pipe"],
  });
  let output = "";
  let err = "";
  child.stdout.on("data", (b) => (output += b));
  child.stderr.on("data", (b) => (err += b));
  const messages = [
    {
      id: 1,
      method: "initialize",
      params: { protocolVersion: "2025-11-25", capabilities: {}, clientInfo: { name: "test", version: "1" } },
    },
    { method: "notifications/initialized" },
    { id: 2, method: "tools/list" },
    { id: 3, method: "tools/call", params: { name: "status", arguments: {} } },
    { id: 4, method: "tools/call", params: { name: "why", arguments: { run: -1 } } },
    { id: 5, method: "tools/call", params: { name: "why", arguments: { run: 999 } } },
    { id: 6, method: "tools/call", params: { name: "request", arguments: { path: "/etc/passwd" } } },
    { id: 7, method: "tools/call", params: { name: "emit", arguments: { id: "a", type: "one" } } },
  ];
  child.stdin.end(messages.map((m) => JSON.stringify({ jsonrpc: "2.0", ...m })).join("\n") + "\n");
  await once(child, "close");
  server.close();
  assert.equal(child.exitCode, 0, err);
  const responses = output
    .trim()
    .split("\n")
    .map((l) => JSON.parse(l));
  assert.equal(responses.length, 7);
  assert.equal(
    responses[0].result.serverInfo.version,
    versionName(),
    "it says which version it is, not a number left behind",
  );
  const get = (id: number) => responses.find((r) => r.id === id);
  assert.equal(get(1).result.protocolVersion, "2025-11-25");
  assert.ok(get(2).result.tools.some((t: any) => t.name === "answer"));
  assert.equal(get(3).result.isError, undefined);
  assert.equal(get(4).error.code, -32602);
  assert.equal(get(5).result.isError, true);
  assert.equal(get(6).error.code, -32602);
  // Calls run side by side, so they can reach the hub in any order.
  assert.deepEqual(calls.toSorted(), [
    ["/v1/events", "Bearer source-key"],
    ["/v1/runs/999/why", "Bearer owner-key"],
    ["/v1/state", "Bearer owner-key"],
  ]);
});

test("U+2028 and U+2029 in a request are part of the line", async () => {
  let told = "";
  const mcp = await connect(async (req, res) => {
    for await (const chunk of req) told += chunk;
    res.end(JSON.stringify({ ok: true }));
  });
  try {
    const text = "第一行 第二行 第三行";
    mcp.send({ id: 2, method: "tools/call", params: { name: "tell", arguments: { key: "k", text } } });
    assert.equal((await mcp.answered(2)).result.isError, undefined);
    assert.deepEqual(JSON.parse(told), { key: "k", text });
    assert.ok(!mcp.answers().some((answer) => answer.error), "and no pieces of it were taken for requests");
  } finally {
    await mcp.close();
  }
});

test("a slow tool call holds up neither a ping nor another call, and is still answered after the input ends", async () => {
  let release = () => {};
  const held = new Promise<void>((resolve) => (release = resolve));
  const mcp = await connect(async (req, res) => {
    if (req.url === "/v1/state") await held;
    res.end(JSON.stringify({ asked: req.url }));
  });
  try {
    mcp.send({ id: 2, method: "tools/call", params: { name: "status", arguments: {} } });
    mcp.send({ id: 3, method: "ping" });
    assert.deepEqual((await mcp.answered(3)).result, {});
    mcp.send({ id: 4, method: "tools/call", params: { name: "why", arguments: { run: 1 } } });
    assert.match((await mcp.answered(4)).result.content[0].text, /runs\/1\/why/);
    assert.ok(!mcp.answers().some((answer) => answer.id === 2), "it's still with the hub");
    mcp.child.stdin.end();
    release();
    assert.match((await mcp.answered(2)).result.content[0].text, /v1\/state/);
    await mcp.closed;
    assert.equal(mcp.child.exitCode, 0);
  } finally {
    release();
    await mcp.close();
  }
});

// Failure modes: a recipe's rules don't pass `agent-autoloop check`, or check would pass anything; a rule names a Skill the
// recipe doesn't ship, or the README doesn't say where to put it; a README promises one access level while the rules give
// another; the curl in ops-alerts no longer reaches its rule, or the outside system's key can set off the restart; the
// issue watcher prints something the worker can't read (a body's line break or backslash breaking its JSON), or an event
// the rules wouldn't let through, or asks GitHub for something else when called with one argument.
import assert from "node:assert/strict";
import { spawn, spawnSync } from "node:child_process";
import { chmodSync, mkdtempSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import { createServer } from "node:http";
import type { AddressInfo } from "node:net";
import { tmpdir } from "node:os";
import { join } from "node:path";
import { after, test } from "node:test";
import { readMessage, resultFrom } from "../worker/contract.ts";

const ROOT = join(import.meta.dirname, "..");
const RECIPES = join(ROOT, "examples", "recipes");
const NAMES = [
  "morning-brief",
  "github-issues",
  "ops-alerts",
  "feedback",
  "website-watch",
  "feishu-brief",
  "inbox-triage",
  "browser-handoff",
];
const scratch = mkdtempSync(join(tmpdir(), "agent-autoloop-recipes-"));
after(() => rmSync(scratch, { recursive: true, force: true }));

const cleanEnv = () =>
  Object.fromEntries(
    Object.entries(process.env).filter(([name]) => !name.startsWith("AGENT_AUTOLOOP_")),
  ) as NodeJS.ProcessEnv;
const agentAutoloop = (args: string[], env: NodeJS.ProcessEnv) =>
  spawnSync(
    process.execPath,
    ["--disable-warning=ExperimentalWarning", join(ROOT, "bin", "agent-autoloop.ts"), ...args],
    {
      env: { ...cleanEnv(), ...env },
      encoding: "utf8",
    },
  );
const readRules = (name: string) => JSON.parse(readFileSync(join(RECIPES, name, "rules.json"), "utf8"));
const readDoc = (name: string) => readFileSync(join(RECIPES, name, "README.md"), "utf8");
const check = (rulesFile: string) =>
  agentAutoloop(["check"], {
    AGENT_AUTOLOOP_RULES: rulesFile,
    AGENT_AUTOLOOP_HOME: mkdtempSync(join(scratch, "home-")),
  });

for (const name of NAMES) {
  test(`${name}: agent-autoloop check passes its rules`, () => {
    const checked = check(join(RECIPES, name, "rules.json"));
    assert.equal(checked.status, 0, checked.stderr);
  });

  test(`${name}: every Skill a rule names is here, and the README says where it goes`, () => {
    const skills = readRules(name).rules.flatMap((rule: { skill?: string }) => rule.skill ?? []);
    assert.equal(skills.length, 1);
    const skill = readFileSync(join(RECIPES, name, "SKILL.md"), "utf8");
    assert.match(skill, new RegExp(`^name: ${skills[0]}$`, "m"));
    assert.match(readDoc(name), new RegExp(`~/\\.codex/skills/${skills[0]}/`));
    assert.match(readDoc(name), new RegExp(`~/\\.claude/skills/${skills[0]}/`));
  });

  test(`${name}: the README states the access level the rules actually give`, () => {
    const { agents } = readRules(name);
    const real = Object.values<{ use: string; access: string }>(agents).filter((agent) => agent.use !== "command");
    assert.equal(real.length, 1);
    const stated = /权限：`(read|edit|full)`/.exec(readDoc(name));
    assert.ok(stated, "README 要写明权限");
    assert.equal(stated[1], real[0].access);
  });
}

test("agent-autoloop check refuses a recipe that was changed for the worse", () => {
  const broken = readRules("morning-brief");
  broken.rules[0].to = "nobody";
  const file = join(scratch, "broken.json");
  writeFileSync(file, JSON.stringify(broken));
  const checked = check(file);
  assert.notEqual(checked.status, 0);
  assert.match(checked.stderr, /不是已登记的 Agent/);
});

async function freePort() {
  const server = createServer();
  await new Promise<void>((resolve) => server.listen(0, "127.0.0.1", resolve));
  const { port } = server.address() as AddressInfo;
  await new Promise((resolve) => server.close(resolve));
  return port;
}

test("ops-alerts: the curl in the README reaches the rule, and that key can't set off the restart", async () => {
  const home = mkdtempSync(join(scratch, "ops-"));
  const port = await freePort();
  const env = { AGENT_AUTOLOOP_HOME: home };
  writeFileSync(join(home, "rules.json"), readFileSync(join(RECIPES, "ops-alerts", "rules.json")));
  const key = agentAutoloop(["key", "new", "source", "shop"], env).stdout.trim().split("\n").at(-1)!;
  const url = `http://127.0.0.1:${port}`;
  writeFileSync(join(home, "config.json"), JSON.stringify({ url, hub: { listen: `127.0.0.1:${port}` } }));
  const hub = spawn(
    process.execPath,
    ["--disable-warning=ExperimentalWarning", join(ROOT, "bin", "agent-autoloop.ts"), "up"],
    { env: { ...cleanEnv(), ...env }, stdio: "ignore" },
  );
  try {
    for (let tries = 0; tries < 100; tries++) {
      const up = await fetch(`${url}/healthz`).catch(() => null);
      if (up?.ok) break;
      await new Promise((resolve) => setTimeout(resolve, 100));
    }
    const curl = /```bash\n(curl [\s\S]*?)```/.exec(readDoc("ops-alerts"))?.[1];
    assert.ok(curl, "README 里要有一条 curl");
    const sent = spawnSync("sh", ["-c", curl.replaceAll("http://127.0.0.1:3350", url)], {
      env: { ...cleanEnv(), SHOP_KEY: key },
      encoding: "utf8",
    });
    assert.equal(sent.status, 0, sent.stderr);
    assert.deepEqual(JSON.parse(sent.stdout).routed, ["查线上报错"]);
    const restart = await fetch(`${url}/v1/events`, {
      method: "POST",
      headers: { authorization: `Bearer ${key}`, "content-type": "application/json" },
      body: JSON.stringify({ id: "from-outside", type: "restart", subject: "checkout" }),
    });
    assert.deepEqual((await restart.json()).routed, []);
  } finally {
    hub.kill("SIGTERM");
    await new Promise((resolve) => hub.once("exit", resolve));
  }
});

// Stands in for gh and does what gh does with --jq, so the watcher's own filter really runs.
const FAKE_GH = `#!/bin/sh
printf '%s\\n' "$*" > "$GH_LOG"
while [ $# -gt 0 ]; do
  [ "$1" = "--jq" ] && filter=$2
  shift
done
exec jq -c "$filter" "$GH_ISSUES"
`;

function watch(args: string[]) {
  const dir = mkdtempSync(join(scratch, "gh-"));
  writeFileSync(join(dir, "gh"), FAKE_GH);
  chmodSync(join(dir, "gh"), 0o755);
  const issues = [
    {
      number: 12,
      title: 'Crash on "C:\\new"',
      url: "https://example.com/issues/12",
      body: 'line one\nline two with a "quote" and a back\\slash\n\ttabbed',
    },
    { number: 13, title: "No body", url: "https://example.com/issues/13", body: "" },
    { number: 14, title: "Long", url: "https://example.com/issues/14", body: "字".repeat(5000) },
  ];
